/**
 * Before we start (punch list #382, PR 2): what has to be true before a stage begins, who said so, and who decided
 * to go. Lifted from the spike the owner approved on 2026-11-17 (`spike/before-we-start`), with its rules unchanged.
 *
 * A stage carries a short list of bullets. A bullet waits on them (the GC, the customer) or on us. A bullet on
 * them is open or a yes, and a yes says how we know: their word, their photo, or we saw it. A bullet that asks for
 * a photo is not a yes on their word alone. A bullet on us is read from the app (the order log, the trip, the
 * permit) and nobody ticks it. The day we decide is our first day less the notice we need. Go and Hold are
 * decisions with a name on them. Nothing here blocks anything: the rules only say where a stage stands and what
 * the next press is.
 *
 * Pure. Days are 'YYYY-MM-DD'. Every sentence marks its values with `val` (`../valuesInPlace`), so a screen draws
 * them in place and a text or an email reads them plain.
 */
import { plainSentence, val } from '../valuesInPlace.ts'

// ---------- What a stage holds ----------

/** How we know a yes: their word, their photo, or one of ours saw it on site. */
export type Know = 'word' | 'photo' | 'saw'

/** A yes on a bullet: how we know, who said or saw it, how it reached us, and the day. */
export type Yes = { know: Know; who: string; how: string; day: string }

/** One ask kept: the day it went out and how (text, email, phone). */
export type Ask = { day: string; how: string }

export type ThemBullet = {
  id: string
  on: 'them'
  words: string
  /** Their word alone leaves it open: it needs their photo, or one of ours on site. */
  wantsPhoto: boolean
  /** Shown on the GC's page, when the job's two switches are on. */
  eye: boolean
  yes: Yes | null
  asks: Ask[]
  /** The day they say it will be true, when they gave one. */
  byDay: string | null
}

/** Where the app reads a bullet on us from. `hand` is ticked by a person of ours. */
export type UsReads = 'order_log' | 'trip' | 'permit' | 'hand'

export type UsBullet = {
  id: string
  on: 'us'
  words: string
  reads: UsReads
  /** What the app read: ready or not. */
  ok: boolean
  /** What the app read, in a few words: "Two lines land Nov 25, six days ahead". */
  fact: string
  /** The press that fixes it: "Open the order log". */
  door: string
  /** Where that press goes, when it is a door to another screen. Absent for a hand tick. */
  href?: string | null
}

export type Bullet = ThemBullet | UsBullet

/** A day they gave for ready: the day, the day they said it, who and how. Every one is kept. */
export type TheirDay = { day: string; said: string; who: string; how: string }

/** Go or Hold: who pressed it, the day, and the words of every bullet that was open then. */
export type Decision = { kind: 'go' | 'hold'; by: string; day: string; openThen: string[] }

/** What one of ours found on arrival: the day, who, and the ids of the bullets that were not as told. */
export type Arrival = { day: string; by: string; notAsTold: string[] }

export type Stage = {
  id: string
  /** The part of the site the stage is on: a building. '' when the site is one part. */
  part: string
  /** The job the stage line is on, as the app prints it. */
  job: string
  /** The stage's name: Top Out. */
  name: string
  /** Our window: our first day and our last day. Null until the office plans the stage's days. */
  window: [string, string] | null
  /** The trip planned for it, when the site is far: the day the crew leaves and the day it is back. */
  trip: [string, string] | null
  finished: boolean
  /** Oldest first. */
  theirDays: TheirDay[]
  bullets: Bullet[]
  decision: Decision | null
  /** Every arrival at the stage, oldest first: a stage can be arrived at more than once (v2.8238). */
  arrivals: Arrival[]
}

/** The site, as the rules need it: the days of notice we need, and who we ask. */
export type Site = { noticeDays: number; contact: string }

// ---------- Days ----------

const at = (ymd: string) => new Date(`${ymd}T12:00:00Z`)
export const addDays = (ymd: string, n: number): string => {
  const d = at(ymd)
  d.setUTCDate(d.getUTCDate() + n)
  return d.toISOString().slice(0, 10)
}
/** Whole days from `a` to `b`. Negative when `b` is before `a`. */
export const daysBetween = (a: string, b: string): number => Math.round((at(b).getTime() - at(a).getTime()) / 864e5)
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
/** Nov 21. */
export const monthDay = (ymd: string): string => `${MONTHS[at(ymd).getUTCMonth()]} ${at(ymd).getUTCDate()}`
/** Sat Nov 21. */
export const weekDay = (ymd: string): string => `${DAYS[at(ymd).getUTCDay()]} ${monthDay(ymd)}`
/** Dec 1 to 12, or Nov 30 to Dec 13 across a month end, or Dec 1 when the span is one day. */
export const daySpan = (a: string, b: string): string => (a === b ? monthDay(a) : at(a).getUTCMonth() === at(b).getUTCMonth() && a.slice(0, 4) === b.slice(0, 4) ? `${monthDay(a)} to ${at(b).getUTCDate()}` : `${monthDay(a)} to ${monthDay(b)}`)
export const countWords = (n: number, one: string, many: string): string => `${n} ${n === 1 ? one : many}`
/** "today", "in 4 days", "3 days ago". */
export function inDaysWords(today: string, ymd: string): string {
  const n = daysBetween(today, ymd)
  if (n === 0) return 'today'
  return n > 0 ? `in ${countWords(n, 'day', 'days')}` : `${countWords(-n, 'day', 'days')} ago`
}

// ---------- A bullet ----------

/** A yes that stands: a bullet that asks for a photo needs more than their word. */
export function bulletIsYes(b: Bullet): boolean {
  if (b.on === 'us') return b.ok
  if (!b.yes) return false
  return !(b.wantsPhoto && b.yes.know === 'word')
}

/** Their word is in, and the bullet still waits on a photo. */
export const waitsOnPhoto = (b: Bullet): boolean => b.on === 'them' && !!b.yes && b.wantsPhoto && b.yes.know === 'word'

export const KNOW_WORDS: Record<Know, string> = { word: 'their word', photo: 'their photo', saw: 'we saw it' }

export const lastAsk = (b: Bullet): Ask | null => (b.on === 'them' && b.asks.length ? (b.asks[b.asks.length - 1] ?? null) : null)

/**
 * The arrival that said No to this bullet, while nobody has given a yes since. Every arrival is read, not the newest
 * alone: with two arrivals the earlier one's No stood on its bullet and its line was not drawn (v2.8366).
 */
export function noOn(s: Stage, b: Bullet): Arrival | null {
  if (bulletIsYes(b)) return null
  for (let i = s.arrivals.length - 1; i >= 0; i--) {
    const a = s.arrivals[i]
    if (a && a.notAsTold.includes(b.id)) return a
  }
  return null
}

/** One of ours said No to this bullet on arrival, and nobody has given a yes since. */
export const saidNo = (s: Stage, b: Bullet): boolean => noOn(s, b) != null

/**
 * The line under a bullet: how we know, or when we asked. Its values are marked: who, how and the day of a yes,
 * the day of the last ask, and the day they say it will be true.
 */
export function bulletLine(b: Bullet): string {
  if (b.on === 'us') return b.fact
  if (b.yes) {
    const base = `${val('who', b.yes.who)}, ${val('how', b.yes.how)}, ${val('day', monthDay(b.yes.day))}.`
    return waitsOnPhoto(b) ? `${base} Still needs a photo.` : base
  }
  const a = lastAsk(b)
  const asked = a ? `Asked ${val('day', monthDay(a.day))} by ${a.how}. No answer yet.` : 'Not asked yet.'
  return b.byDay ? `${asked} They say by ${val('by', monthDay(b.byDay))}.` : asked
}

// ---------- A stage ----------

/**
 * How ready a list is, as a share of its bullets: 5 of 6 is 83%. Every bullet counts the same. It reads 100% only
 * when every bullet has a yes that stands, so 199 of 200 is 99%, never rounded up to ready.
 */
export function readiness(bullets: readonly Bullet[]): { yes: number; total: number; pct: number } {
  const total = bullets.length
  const yes = bullets.filter(bulletIsYes).length
  return { yes, total, pct: total ? (yes === total ? 100 : Math.floor((yes / total) * 100)) : 0 }
}

/** A box on the ready bar: a green check, a red cross for a real No, or empty. */
export type ReadyMark = 'yes' | 'no' | 'open'

/** The ready bar's boxes, one a bullet: the ready ones first, then a No, then the open ones. */
export function readyMarks(s: Stage): ReadyMark[] {
  const open = s.bullets.filter((b) => !bulletIsYes(b))
  const no = open.filter((b) => saidNo(s, b)).length
  return [...Array<ReadyMark>(s.bullets.length - open.length).fill('yes'), ...Array<ReadyMark>(no).fill('no'), ...Array<ReadyMark>(open.length - no).fill('open')]
}

export const openBullets = (s: Stage): Bullet[] => s.bullets.filter((b) => !bulletIsYes(b))
export const metBullets = (s: Stage): Bullet[] => s.bullets.filter(bulletIsYes)
export const openOnThem = (s: Stage): ThemBullet[] => openBullets(s).filter((b): b is ThemBullet => b.on === 'them')
export const openOnUs = (s: Stage): UsBullet[] => openBullets(s).filter((b): b is UsBullet => b.on === 'us')

/** The day we decide, go or no-go: our first day less the notice we need. Null while the stage has no days. */
export const goNoGoDay = (s: Stage, site: Site): string | null => (s.window ? addDays(s.window[0], -site.noticeDays) : null)
/** The day before the crew leaves: the last look at a go made on a promise. */
export function lastCheckDay(s: Stage): string | null {
  const first = (s.trip ?? s.window)?.[0]
  return first ? addDays(first, -1) : null
}
/** Their newest day for ready. */
export const theirDay = (s: Stage): TheirDay | null => (s.theirDays.length ? (s.theirDays[s.theirDays.length - 1] ?? null) : null)
/** How far they have moved the day they said it would be ready, first day to newest. Never below zero. */
export function movedDays(s: Stage): number {
  const first = s.theirDays[0]
  const newest = theirDay(s)
  return first && newest && s.theirDays.length > 1 ? Math.max(0, daysBetween(first.day, newest.day)) : 0
}
/** They say ready after our first day. */
export function startClash(s: Stage): boolean {
  const t = theirDay(s)
  return !!t && !!s.window && t.day > s.window[0]
}

// ---------- Where a stage stands ----------

/**
 * The kinds a sentence here marks. Four can be changed where they stand: our first day, the day they gave, the
 * notice we need and who we ask. The rest are worked out and only read.
 */
export type ValueKind = 'start' | 'their' | 'notice' | 'contact' | 'decide' | 'count' | 'check' | 'who' | 'how' | 'day' | 'by'
export const CHANGEABLE_VALUES: ReadonlySet<ValueKind> = new Set<ValueKind>(['start', 'their', 'notice', 'contact'])
const mark = (kind: ValueKind, text: string): string => val(kind, text)

export type Light = 'green' | 'amber' | 'red' | 'grey'
/** The one press a stage offers next. */
export type NextPress = 'ask' | 'decide' | 'go' | 'move' | 'ours' | 'write' | 'plan' | 'look' | 'none'
export type Standing = { light: Light; headline: string; sentence: string; next: NextPress; nextLabel: string | null }

/** How near the day to decide must be before a stage asks for anything. */
export const ASK_WITHIN_DAYS = 14
/** An ask this fresh is still out: the next press is the decision, not a second ask. */
export const ASKED_FRESH_DAYS = 2

/**
 * Where a stage stands, as one sentence and one press. The order of the questions is the order a person would ask
 * them: is there a list, do we have our days, does a No from arrival still stand, is it decided, do their day and ours
 * disagree, what is still open, and how close is the day we must decide. The first that fits is the stage's
 * sentence. A stage line has no days until the office plans them on the Stage Plan, so that row is the build's own.
 */
export function stageStanding(s: Stage, site: Site, today: string): Standing {
  if (s.finished) return { light: 'grey', headline: 'Done', sentence: 'This stage is finished.', next: 'none', nextLabel: null }
  if (!s.bullets.length) return { light: 'grey', headline: 'No list yet', sentence: 'Nobody has written what must be true before this stage.', next: 'write', nextLabel: 'Write the list' }
  if (!s.window) return { light: 'grey', headline: 'No days yet', sentence: 'We have not planned our days for this stage.', next: 'plan', nextLabel: 'Plan our days' }
  const decideBy = addDays(s.window[0], -site.noticeDays)
  // Red while a No stands on a bullet with no yes since. Once the office or the customer gives a new yes on every No,
  // the stage goes back to its own rows: the new yes is the one the crew is asked to look at (v2.8238), and the stage
  // read Not as told until one of ours answered again (v2.8367).
  const notAsTold = s.bullets.find((b) => noOn(s, b))
  const arrived = notAsTold ? noOn(s, notAsTold) : null
  if (notAsTold && arrived) {
    return {
      light: 'red',
      headline: 'Not as told',
      sentence: `${mark('who', arrived.by)} got there ${mark('day', monthDay(arrived.day))} and it was not as told: ${notAsTold.words}`,
      next: 'look',
      nextLabel: 'Open the stage',
    }
  }
  const them = openOnThem(s)
  const us = openOnUs(s)
  const daysLeft = daysBetween(today, decideBy)
  const start = mark('start', weekDay(s.window[0]))
  const contact = mark('contact', site.contact)
  if (s.decision?.kind === 'go') {
    const still = openBullets(s).length
    const pressed = `${mark('who', s.decision.by)} pressed Go ${mark('day', monthDay(s.decision.day))}`
    if (!still) return { light: 'green', headline: 'Go', sentence: `Crew confirmed for ${start}. ${pressed}.`, next: 'none', nextLabel: null }
    // A go on their promise comes back to the office the day before the crew leaves: the last check.
    const lastCheck = lastCheckDay(s) ?? s.window[0]
    if (daysBetween(today, lastCheck) <= 0) {
      const open = mark('count', countWords(still, 'thing', 'things'))
      return {
        light: 'red',
        headline: 'Last check',
        sentence: `${pressed} with ${open} open. The last check ${today === lastCheck ? `is ${mark('check', 'today')}` : `was ${mark('check', weekDay(lastCheck))}`}.`,
        next: 'decide',
        nextLabel: 'Go or hold',
      }
    }
    return {
      light: 'amber',
      headline: 'Go, on a promise',
      sentence: `${pressed} with ${mark('count', countWords(still, 'thing', 'things'))} open. Last check ${mark('check', weekDay(lastCheckDay(s) ?? s.window[0]))}.`,
      next: them.length ? 'ask' : 'ours',
      nextLabel: them.length ? `Ask ${site.contact}` : (us[0]?.door ?? null),
    }
  }
  const t = theirDay(s)
  if (t && startClash(s)) {
    return { light: 'red', headline: 'Their day is after ours', sentence: `${mark('who', t.who)} says ready ${mark('their', monthDay(t.day))}. We planned to start ${start}.`, next: 'move', nextLabel: 'Move our start' }
  }
  const held = s.decision?.kind === 'hold' ? `On hold since ${mark('day', monthDay(s.decision.day))}. ` : ''
  if (!them.length && !us.length) return { light: 'green', headline: 'Everything has a yes', sentence: `${held}Nothing is open. Press Go to confirm the crew for ${start}.`, next: 'go', nextLabel: 'Go' }
  const decide = mark('decide', weekDay(decideBy))
  const when = daysLeft < 0 ? `We should have decided ${decide}.` : daysLeft === 0 ? `We decide ${mark('decide', 'today')}.` : `We decide by ${decide}, ${inDaysWords(today, decideBy)}.`
  if (!them.length) {
    const ours = mark('count', countWords(us.length, 'thing of ours', 'things of ours'))
    return {
      light: daysLeft <= 0 ? 'red' : 'amber',
      headline: 'Ours to do',
      sentence: `${held}${contact} is done. ${ours} ${us.length === 1 ? 'is' : 'are'} not ready. ${when}`,
      next: daysLeft <= 0 ? 'decide' : 'ours',
      nextLabel: daysLeft <= 0 ? 'Go or hold' : (us[0]?.door ?? null),
    }
  }
  const waiting = `${held}Waiting on ${contact} for ${mark('count', countWords(them.length, 'thing', 'things'))}${us.length ? `, and ${mark('count', String(us.length))} of ours` : ''}. ${when}`
  if (daysLeft <= 0) return { light: 'red', headline: 'Decide now', sentence: waiting, next: 'decide', nextLabel: 'Go or hold' }
  if (daysLeft <= ASK_WITHIN_DAYS) {
    const askedAll = them.every((b) => {
      const a = lastAsk(b)
      return !!a && daysBetween(a.day, today) <= ASKED_FRESH_DAYS
    })
    return { light: 'amber', headline: 'Waiting on them', sentence: waiting, next: askedAll ? 'decide' : 'ask', nextLabel: askedAll ? 'Go or hold' : `Ask ${site.contact}` }
  }
  return {
    light: 'grey',
    headline: 'Later',
    sentence: `${held}${mark('count', countWords(them.length + us.length, 'thing', 'things'))} open. Nothing to do until ${mark('check', monthDay(addDays(decideBy, -ASK_WITHIN_DAYS)))}.`,
    next: 'none',
    nextLabel: null,
  }
}

// ---------- The site ----------

export const stagesAhead = (stages: readonly Stage[]): Stage[] => stages.filter((s) => !s.finished)

const TROUBLE: Record<Light, number> = { red: 0, amber: 1, green: 2, grey: 3 }
/** A stage with no days sorts after every stage that has them. */
const firstDay = (s: Stage): string => s.window?.[0] ?? '9999-12-31'

/** The stages ahead, sorted by trouble: red, then amber, green, grey, and by first day inside a colour. */
export function byTrouble(stages: readonly Stage[], site: Site, today: string): Stage[] {
  return stagesAhead(stages)
    .map((s) => ({ s, light: stageStanding(s, site, today).light }))
    .sort((a, b) => TROUBLE[a.light] - TROUBLE[b.light] || firstDay(a.s).localeCompare(firstDay(b.s)) || a.s.id.localeCompare(b.s.id))
    .map((x) => x.s)
}

/** The stages whose open bullets on them are worth one ask now: something is open on them, and the day to decide is near. */
export function stagesToAsk(stages: readonly Stage[], site: Site, today: string): Stage[] {
  return stagesAhead(stages).filter((s) => {
    const decideBy = goNoGoDay(s, site)
    return decideBy != null && openOnThem(s).length > 0 && daysBetween(today, decideBy) <= ASK_WITHIN_DAYS
  })
}

/** How many answers they owe us across those stages. */
export const answersOwed = (stages: readonly Stage[], site: Site, today: string): number => stagesToAsk(stages, site, today).reduce((n, s) => n + openOnThem(s).length, 0)

/** The days they have moved on this site, across every stage ahead. */
export const siteMovedDays = (stages: readonly Stage[]): number => stagesAhead(stages).reduce((n, s) => n + movedDays(s), 0)

/** The banner over the site's stages: what they owe us, as one sentence. */
export function siteBanner(stages: readonly Stage[], site: Site, today: string): { sentence: string; askLabel: string | null } {
  const toAsk = stagesToAsk(stages, site, today)
  const n = toAsk.reduce((sum, s) => sum + openOnThem(s).length, 0)
  if (!n) return { sentence: `Nothing to ask ${mark('contact', site.contact)} right now.`, askLabel: null }
  return {
    sentence: `${mark('contact', site.contact)} owes us ${mark('count', countWords(n, 'answer', 'answers'))} on ${mark('count', countWords(toAsk.length, 'stage', 'stages'))}.`,
    askLabel: n === 1 ? `Ask ${site.contact} about 1` : `Ask ${site.contact} about all ${n}`,
  }
}

/** A stage as a message names it: Lodge top out, or top out when the site is one part. */
const stageInWords = (s: Stage): string => `${s.part ? `${s.part} ` : ''}${s.name.toLowerCase()}`

export type AskOptions = {
  /** Their page shows what we need, so the ask may point them to it. Off until the job's two switches are on. */
  page?: boolean
  /** The sentence that says a wasted trip is billed. Off until the owner writes it. */
  wastedTrip?: string | null
}

/**
 * The ask, written for the office to read and change: one message to one person, across every stage it covers.
 * A bullet that asks for a photo says so. Nothing sends it. It is plain words, with no marks.
 */
export function askText(site: Site, stages: readonly Stage[], options: AskOptions = {}): string {
  const lines: string[] = [`${site.contact}, a few things before we lock in our crew.`]
  for (const s of stages) {
    const open = openOnThem(s)
    if (!open.length) continue
    lines.push('')
    const name = stageInWords(s).replace(/^./, (c) => c.toUpperCase())
    lines.push(s.window ? `${name}, we plan ${weekDay(s.window[0])} and decide by ${weekDay(addDays(s.window[0], -site.noticeDays))}:` : `${name}:`)
    open.forEach((b, i) => lines.push(`${i + 1}. ${b.words}${b.wantsPhoto ? ' A photo would settle it.' : ''}`))
  }
  lines.push('')
  lines.push(`A yes or a not yet on each is all we need.${options.page ? ' Or tap to answer on your page.' : ''}`)
  if (options.wastedTrip?.trim()) lines.push(options.wastedTrip.trim())
  return lines.join('\n')
}

/** The words on the Ask panel. */
export const ASK_WORDS = {
  lead: (stages: number) => `One message for ${countWords(stages, 'stage', 'stages')}. Change any word. Nothing goes out by itself.`,
  textIt: 'Text it',
  emailIt: 'Email it',
  copy: 'Copy',
  another: 'Sent it another way?',
  texted: 'I texted it',
  emailed: 'I emailed it',
  called: 'I called',
  boxLead: 'This is their box in Messages, filled with the ask. Nothing is sent until you send it there.',
  noThread: 'This job names no customer to message. Copy the ask and send it your way.',
  holdLead: 'A hold tells nobody by itself. Change any word, then send the note.',
  holdBoxLead: 'This is their box in Messages, filled with the note. Nothing is sent until you send it there.',
  holdNoThread: 'This job names no customer to message. Copy the note and send it your way.',
} as const

/** The words on Go or hold. Nothing here is blocked: a crew can be scheduled with no Go. */
export const DECIDE_WORDS = {
  title: 'Go or hold?',
  allYes: 'Everything on the list has a yes.',
  go: 'Go',
  goOnPromise: 'Go, on their promise',
  hold: 'Hold',
  holdLead: 'Keep the crew home, and move our start to this day.',
  notBlocked: 'Nothing is blocked. A crew can be scheduled with no Go.',
  takeBack: 'Take the Go back',
  takeHoldBack: 'Take the hold back',
  noDays: 'Plan our days for this stage first. A hold moves them.',
} as const

/** What Go does, under its name: the crew goes for our first day, and a go on a promise comes back for a last check. */
export function goWords(s: Stage): string {
  const start = s.window ? `Send the crew for ${weekDay(s.window[0])}.` : 'Send the crew. Our days are not planned yet.'
  if (!openBullets(s).length) return `${start} ${DECIDE_WORDS.allYes}`
  const check = lastCheckDay(s)
  return `${start} This is a go on their promise.${check ? ` It comes back to you ${weekDay(check)}, the day before the crew leaves.` : ''}`
}

/** What is still open, as the panel says it before the two presses. */
export function openWords(s: Stage): string {
  const open = openBullets(s)
  return open.length ? `${countWords(open.length, 'thing is', 'things are')} still open.` : DECIDE_WORDS.allYes
}

/** The decision that stands, as the stage's foot says it: Go, Dana, Nov 12. */
export function decisionWords(d: Decision): string {
  return d.kind === 'go' ? `Go. ${val('who', d.by)}, ${val('day', monthDay(d.day))}.` : `On hold. ${val('who', d.by)}, ${val('day', monthDay(d.day))}.`
}

/**
 * The hold note, written for the office to read, change and send. A hold tells nobody by itself. It is plain
 * words, with no marks.
 */
export function holdText(site: Site, s: Stage, newStart: string): string {
  const open = openOnThem(s)
  const lines = [`${site.contact}, we are holding our start on the ${stageInWords(s)}.${s.window ? ` We planned ${weekDay(s.window[0])}.` : ''}`]
  if (open.length) {
    lines.push(open.length === 1 ? 'We cannot send a crew until this is true:' : 'We cannot send a crew until these are true:')
    open.forEach((b, i) => lines.push(`${i + 1}. ${b.words}`))
  }
  lines.push(`Our next opening is ${weekDay(newStart)}. Tell us the day it is ready and we will lock it in.`)
  return lines.join('\n')
}

// ---------- The list behind the ready bar ----------

/** What resting on the ready bar lists: what it takes to start the stage, the open bullets first, then the ones with a yes. */
export type ReadyList = {
  title: string
  /** 5 of 6 ready, which is 83%. Every bullet counts the same. */
  count: string
  open: Array<{ id: string; words: string; line: string; no: boolean }>
  met: Array<{ id: string; words: string }>
}

export function readyList(s: Stage): ReadyList {
  const ready = readiness(s.bullets)
  const open = openBullets(s)
  const line = (b: Bullet): string => {
    const no = noOn(s, b)
    if (no) return `${no.by} said No on site, ${monthDay(no.day)}.`
    return b.on === 'us' ? `Ours. ${b.fact}` : plainSentence(bulletLine(b))
  }
  return {
    title: open.length ? `What it takes to start ${s.name}` : `${s.name} has every yes`,
    count: `${ready.yes} of ${ready.total} ready, which is ${ready.pct}%. Every bullet counts the same.`,
    // A No first, as the bar draws it.
    open: [...open.filter((b) => saidNo(s, b)), ...open.filter((b) => !saidNo(s, b))].map((b) => ({ id: b.id, words: b.words, line: line(b), no: saidNo(s, b) })),
    met: metBullets(s).map((b) => ({ id: b.id, words: b.words })),
  }
}

/** The Schedule look on the strip of looks: how many stages are ahead, and in amber what they owe us. */
export function scheduleLookWords(stages: readonly Stage[], site: Site, today: string): { n: number; count: string; need: string | null } {
  const ahead = stagesAhead(stages).length
  const owed = answersOwed(stages, site, today)
  return { n: ahead, count: countWords(ahead, 'stage', 'stages'), need: owed ? `${countWords(owed, 'answer', 'answers')} owed` : null }
}

/** Under the banner: how far they have moved on this site so far, or nothing when they have not. */
export function siteMovedWords(stages: readonly Stage[]): string | null {
  const moved = siteMovedDays(stages)
  return moved ? `They have moved ${countWords(moved, 'day', 'days')} on this site so far.` : null
}

// ---------- The GC's page ----------

/** The job's two switches: it shares its stage dates, and it shows what we need before each stage. */
export type GcPageSwitches = { sharesStageDates: boolean; showsWhatWeNeed: boolean }

/** A new bullet's eye: one on them starts shown, one on us is never shown. */
export const startsShown = (on: Bullet['on']): boolean => on === 'them'

/**
 * What the GC's page may show of a stage: the bullets on them with the eye on, and only while both of the job's
 * switches are on. Never a bullet of ours, whatever its row says.
 */
export function sharedBullets(s: Stage, switches: GcPageSwitches): ThemBullet[] {
  if (!switches.sharesStageDates || !switches.showsWhatWeNeed) return []
  return s.bullets.filter((b): b is ThemBullet => b.on === 'them' && b.eye)
}

/** After our Go with nothing open, their page reads crew confirmed. That firm date is what they get for answering. */
export const crewConfirmed = (s: Stage): boolean => s.decision?.kind === 'go' && openBullets(s).length === 0

/** How a settled bullet reads on their page: how we know, with no name of ours. */
export function settledWords(b: ThemBullet): string {
  if (!b.yes) return ''
  if (b.yes.know === 'saw') return 'we saw it on site'
  return b.yes.know === 'photo' ? `your photo, ${monthDay(b.yes.day)}` : `you told us ${monthDay(b.yes.day)}`
}

// ---------- The crew's phone ----------

/** What the crew looks at on arrival: the bullets on them that nobody of ours has seen. */
export const toLookAt = (s: Stage): ThemBullet[] => s.bullets.filter((b): b is ThemBullet => b.on === 'them' && !(b.yes && b.yes.know === 'saw'))

/** The sentence a place that cannot draw a value apart prints: a tooltip, a text, a row's name. */
export const standingInWords = (s: Stage, site: Site, today: string): string => plainSentence(stageStanding(s, site, today).sentence)
